package dev.knowledge.platform.storage;

import java.io.InputStream;

/**
 * Original-file storage. Keys are generated by the server as {@code org/<orgId>/doc/<docId>/v<n>/<sha256>} so a key
 * can never be chosen by a client or escape its tenant prefix.
 */
public interface ObjectStore {
    void put(String key, byte[] bytes, String contentType);
    InputStream get(String key);
    void delete(String key);
    String health();
    static String key(java.util.UUID orgId, java.util.UUID documentId, int version, String sha256) {
        if (!sha256.matches("[a-f0-9]{64}")) throw new IllegalArgumentException("Invalid object hash");
        return "org/" + orgId + "/doc/" + documentId + "/v" + version + "/" + sha256;
    }
}
